#!/usr/bin/env python3
"""Round 27: the radio-link texts in every language of Órbita (orbita/static/i18n/<code>.json) and in idioma.js (en, pt)."""
import json, os, sys

K = ['Radioenlaces', 'Cadenas de microondas de torre en torre: donde no hay fibra entre pueblos, y las rutas rápidas de la bolsa.', 'Radioenlace de microondas',
     'Aquí internet viaja por el aire: de torre en torre, por microondas, siempre a la vista. Se usa donde tender fibra no compensa o no es posible, como el hielo, el desierto o el mar entre islas. La posición de cada torre no es pública: la línea une los pueblos que nombran las fuentes.',
     'radioenlaces de microondas, punteados, donde no hay fibra',
     'Por aquí viajan las órdenes de bolsa entre dos mercados. Por el aire la señal llega antes que por la fibra, porque la luz va más despacio dentro del vidrio, y en la bolsa cada millonésima de segundo cuenta. La línea une los dos extremos: las torres no se dibujan.',
     'Latencia publicada']
T = {'en': ['Radio links', 'Microwave chains from tower to tower: where no fibre runs between towns, and the fast routes of the stock exchanges.', 'Microwave radio link', 'Here the internet travels through the air: from tower to tower, by microwave, always in line of sight. It is used where laying fibre does not pay or is not possible, such as ice, desert or the sea between islands. The position of each tower is not public: the line joins the towns the sources name.', 'microwave radio links, dotted, where there is no fibre', 'Stock-exchange orders travel here between two markets. Through the air the signal arrives sooner than through fibre, because light travels more slowly inside glass, and on the stock exchange every millionth of a second counts. The line joins the two ends: the towers are not drawn.', 'Published latency'], 'pt': ['Radioenlaces', 'Cadeias de micro-ondas de torre em torre: onde não há fibra entre as localidades, e as rotas rápidas da bolsa.', 'Radioenlace de micro-ondas', 'Aqui a internet viaja pelo ar: de torre em torre, por micro-ondas, sempre em linha de vista. Usa-se onde instalar fibra não compensa ou não é possível, como no gelo, no deserto ou no mar entre ilhas. A posição de cada torre não é pública: a linha une as localidades que as fontes nomeiam.', 'radioenlaces de micro-ondas, pontilhados, onde não há fibra', 'Por aqui viajam as ordens da bolsa entre dois mercados. Pelo ar o sinal chega antes do que pela fibra, porque a luz anda mais devagar dentro do vidro, e na bolsa cada milionésimo de segundo conta. A linha une os dois extremos: as torres não são desenhadas.', 'Latência publicada'], 'pt-pt': ['Feixes hertzianos', 'Cadeias de micro-ondas de torre em torre: onde não há fibra entre as localidades, e as rotas rápidas da bolsa.', 'Feixe hertziano de micro-ondas', 'Aqui a internet viaja pelo ar: de torre em torre, por micro-ondas, sempre em linha de vista. Usa-se onde instalar fibra não compensa ou não é possível, como no gelo, no deserto ou no mar entre ilhas. A posição de cada torre não é pública: a linha une as localidades que as fontes nomeiam.', 'feixes hertzianos de micro-ondas, pontilhados, onde não há fibra', 'Por aqui viajam as ordens de bolsa entre dois mercados. Pelo ar o sinal chega antes do que pela fibra, porque a luz anda mais devagar dentro do vidro, e na bolsa cada milionésimo de segundo conta. A linha une os dois extremos: as torres não são desenhadas.', 'Latência publicada'], 'fr': ['Faisceaux hertziens', 'Chaînes de micro-ondes de pylône en pylône : là où aucune fibre ne relie les localités, et les routes rapides de la Bourse.', 'Faisceau hertzien', 'Ici, internet passe par les airs : de pylône en pylône, par micro-ondes, toujours en visibilité directe. On l’utilise là où poser de la fibre n’est pas rentable ou pas possible, comme sur la glace, dans le désert ou en mer entre des îles. La position de chaque pylône n’est pas publique : la ligne relie les localités que citent les sources.', 'faisceaux hertziens, en pointillés, là où il n’y a pas de fibre', 'Ici circulent les ordres de Bourse entre deux marchés. Par les airs, le signal arrive plus tôt que par la fibre, car la lumière va moins vite dans le verre, et en Bourse chaque millionième de seconde compte. La ligne relie les deux extrémités : les pylônes ne sont pas dessinés.', 'Latence publiée'], 'de': ['Richtfunk', 'Mikrowellenketten von Mast zu Mast: wo keine Glasfaser die Orte verbindet, und die schnellen Routen der Börse.', 'Richtfunkstrecke', 'Hier reist das Internet durch die Luft: von Mast zu Mast, per Mikrowelle, immer mit Sichtverbindung. Man nutzt es, wo sich Glasfaser nicht lohnt oder nicht möglich ist, etwa auf Eis, in der Wüste oder über dem Meer zwischen Inseln. Die Lage der einzelnen Masten ist nicht öffentlich: Die Linie verbindet die Orte, die die Quellen nennen.', 'Richtfunkstrecken, gepunktet, wo es keine Glasfaser gibt', 'Hier laufen Börsenaufträge zwischen zwei Märkten. Durch die Luft kommt das Signal früher an als durch Glasfaser, weil Licht im Glas langsamer ist, und an der Börse zählt jede Millionstelsekunde. Die Linie verbindet die beiden Enden: Die Masten sind nicht eingezeichnet.', 'Veröffentlichte Latenz'], 'it': ['Ponti radio', 'Catene di microonde da torre a torre: dove nessuna fibra collega i centri abitati, e le rotte veloci della Borsa.', 'Ponte radio a microonde', 'Qui internet viaggia nell’aria: da torre a torre, a microonde, sempre in linea di vista. Si usa dove posare la fibra non conviene o non è possibile, come sul ghiaccio, nel deserto o sul mare tra le isole. La posizione di ogni torre non è pubblica: la linea unisce i centri che citano le fonti.', 'ponti radio a microonde, punteggiati, dove non c’è fibra', 'Qui viaggiano gli ordini di Borsa tra due mercati. Nell’aria il segnale arriva prima che nella fibra, perché la luce va più piano dentro il vetro, e in Borsa conta ogni milionesimo di secondo. La linea unisce i due estremi: le torri non sono disegnate.', 'Latenza pubblicata'], 'nl': ['Straalverbindingen', 'Microgolfketens van mast naar mast: waar geen glasvezel tussen de plaatsen loopt, en de snelle routes van de beurs.', 'Microgolfstraalverbinding', 'Hier reist het internet door de lucht: van mast naar mast, via microgolven, altijd in zichtlijn. Het wordt gebruikt waar glasvezel niet loont of niet kan, zoals op ijs, in de woestijn of over zee tussen eilanden. De ligging van elke mast is niet openbaar: de lijn verbindt de plaatsen die de bronnen noemen.', 'microgolfstraalverbindingen, gestippeld, waar geen glasvezel is', 'Hier reizen beursorders tussen twee markten. Door de lucht komt het signaal eerder aan dan door glasvezel, omdat licht in glas trager gaat, en op de beurs telt elke miljoenste seconde. De lijn verbindt de twee uiteinden: de masten worden niet getekend.', 'Gepubliceerde latentie'], 'sv': ['Radiolänkar', 'Mikrovågskedjor från mast till mast: där ingen fiber går mellan orterna, och börsens snabba rutter.', 'Mikrovågslänk', 'Här färdas internet genom luften: från mast till mast, med mikrovågor, alltid med fri sikt. Det används där fiber inte lönar sig eller inte går att dra, som på is, i öken eller över havet mellan öar. Varje masts läge är inte offentligt: linjen förbinder de orter som källorna nämner.', 'mikrovågslänkar, prickade, där det inte finns fiber', 'Här färdas börsorder mellan två marknader. Genom luften kommer signalen fram tidigare än genom fiber, eftersom ljuset går långsammare i glas, och på börsen räknas varje miljondels sekund. Linjen förbinder de två ändarna: masterna ritas inte ut.', 'Publicerad latens'], 'da': ['Radiokæder', 'Mikrobølgekæder fra mast til mast: hvor der ikke går fiber mellem byerne, og børsens hurtige ruter.', 'Mikrobølgeforbindelse', 'Her rejser internettet gennem luften: fra mast til mast, med mikrobølger, altid med frit udsyn. Det bruges, hvor fiber ikke kan betale sig eller ikke er muligt, som på is, i ørken eller over havet mellem øer. Den enkelte masts placering er ikke offentlig: linjen forbinder de byer, kilderne nævner.', 'mikrobølgeforbindelser, prikkede, hvor der ikke er fiber', 'Her rejser børsordrer mellem to markeder. Gennem luften når signalet frem før end gennem fiber, fordi lyset bevæger sig langsommere i glas, og på børsen tæller hver milliontedel af et sekund. Linjen forbinder de to ender: masterne er ikke tegnet.', 'Offentliggjort latens'], 'nb': ['Radiolinjer', 'Mikrobølgekjeder fra mast til mast: der det ikke går fiber mellom stedene, og børsens raske ruter.', 'Mikrobølgelinje', 'Her reiser internett gjennom luften: fra mast til mast, med mikrobølger, alltid med fri sikt. Det brukes der fiber ikke lønner seg eller ikke er mulig, som på isen, i ørkenen eller over havet mellom øyer. Plasseringen av hver mast er ikke offentlig: linjen binder sammen stedene kildene nevner.', 'mikrobølgelinjer, prikkete, der det ikke finnes fiber', 'Her reiser børsordrer mellom to markeder. Gjennom luften kommer signalet fram før enn gjennom fiber, fordi lyset går saktere i glass, og på børsen teller hver milliondels sekund. Linjen binder sammen de to endene: mastene er ikke tegnet inn.', 'Publisert forsinkelse'], 'fi': ['Radiolinkit', 'Mikroaaltoketjuja mastosta mastoon: siellä, missä paikkakuntien välillä ei ole kuitua, ja pörssin nopeat reitit.', 'Mikroaaltolinkki', 'Täällä internet kulkee ilmassa: mastosta mastoon mikroaalloilla, aina näköyhteydellä. Sitä käytetään siellä, missä kuidun vetäminen ei kannata tai ei ole mahdollista, kuten jäällä, aavikolla tai saarten välisellä merellä. Mastojen sijainnit eivät ole julkisia: viiva yhdistää lähteiden mainitsemat paikkakunnat.', 'mikroaaltolinkit, pisteviivalla, missä kuitua ei ole', 'Täällä pörssitoimeksiannot kulkevat kahden markkinan välillä. Ilmassa signaali ehtii perille nopeammin kuin kuidussa, koska valo kulkee lasissa hitaammin, ja pörssissä jokainen sekunnin miljoonasosa ratkaisee. Viiva yhdistää kaksi päätä: mastoja ei piirretä.', 'Julkaistu viive'], 'is': ['Örbylgjusambönd', 'Örbylgjukeðjur frá mastri til masturs: þar sem enginn ljósleiðari liggur milli byggða, og hraðleiðir kauphallanna.', 'Örbylgjusamband', 'Hér fer internetið um loftið: frá mastri til masturs, með örbylgjum, alltaf í sjónlínu. Það er notað þar sem ljósleiðari borgar sig ekki eða er ekki mögulegur, eins og á ís, í eyðimörk eða yfir haf milli eyja. Staðsetning hvers masturs er ekki opinber: línan tengir byggðirnar sem heimildirnar nefna.', 'örbylgjusambönd, punktalína, þar sem enginn ljósleiðari er', 'Hér fara pantanir á verðbréfamarkaði milli tveggja markaða. Um loftið berst merkið fyrr en um ljósleiðara, því ljósið fer hægar í gleri, og í kauphöllinni skiptir hver milljónasti hluti úr sekúndu máli. Línan tengir endana tvo: möstrin eru ekki teiknuð.', 'Birt töf'], 'pl': ['Radiolinie', 'Łańcuchy mikrofalowe od masztu do masztu: tam, gdzie między miejscowościami nie ma światłowodu, i szybkie trasy giełdy.', 'Radiolinia mikrofalowa', 'Tu internet biegnie powietrzem: od masztu do masztu, mikrofalami, zawsze w linii wzroku. Stosuje się je tam, gdzie światłowód się nie opłaca lub jest niemożliwy, jak na lodzie, na pustyni czy nad morzem między wyspami. Położenie poszczególnych masztów nie jest publiczne: linia łączy miejscowości wymienione w źródłach.', 'radiolinie mikrofalowe, kropkowane, tam gdzie nie ma światłowodu', 'Tędy biegną zlecenia giełdowe między dwoma rynkami. Powietrzem sygnał dociera szybciej niż światłowodem, bo światło w szkle porusza się wolniej, a na giełdzie liczy się każda milionowa część sekundy. Linia łączy oba końce: maszty nie są rysowane.', 'Opublikowane opóźnienie'], 'uk': ['Радіорелейні лінії', 'Мікрохвильові ланцюги від вежі до вежі: там, де між населеними пунктами немає оптоволокна, і швидкі маршрути біржі.', 'Мікрохвильова радіорелейна лінія', 'Тут інтернет передається повітрям: від вежі до вежі, мікрохвилями, завжди в прямій видимості. Його використовують там, де прокладати оптоволокно невигідно або неможливо: на кризі, у пустелі чи над морем між островами. Розташування кожної вежі не є публічним: лінія з’єднує населені пункти, названі в джерелах.', 'мікрохвильові радіорелейні лінії, пунктиром, де немає оптоволокна', 'Тут між двома ринками передаються біржові заявки. Повітрям сигнал доходить швидше, ніж оптоволокном, бо світло у склі рухається повільніше, а на біржі важить кожна мільйонна частка секунди. Лінія з’єднує два кінці: вежі не показано.', 'Опублікована затримка'], 'ru': ['Радиорелейные линии', 'Микроволновые цепочки от вышки к вышке: там, где между населёнными пунктами нет оптоволокна, и быстрые маршруты биржи.', 'Микроволновая радиорелейная линия', 'Здесь интернет передаётся по воздуху: от вышки к вышке, микроволнами, всегда в прямой видимости. Его используют там, где прокладывать оптоволокно невыгодно или невозможно: на льду, в пустыне или над морем между островами. Расположение каждой вышки не публикуется: линия соединяет населённые пункты, названные в источниках.', 'микроволновые радиорелейные линии, пунктиром, где нет оптоволокна', 'Здесь между двумя рынками идут биржевые заявки. По воздуху сигнал приходит раньше, чем по оптоволокну, потому что свет в стекле движется медленнее, а на бирже важна каждая миллионная доля секунды. Линия соединяет два конца: вышки не показаны.', 'Опубликованная задержка'], 'tr': ['Radyolink hatları', 'Kuleden kuleye mikrodalga zincirleri: kasabalar arasında fiber olmayan yerlerde ve borsanın hızlı rotalarında.', 'Mikrodalga radyolink', 'Burada internet havadan gider: kuleden kuleye, mikrodalgayla, her zaman görüş hattında. Fiber döşemenin kârlı ya da mümkün olmadığı yerlerde kullanılır; buz, çöl ya da adalar arasındaki deniz gibi. Her kulenin konumu kamuya açık değildir: çizgi, kaynakların andığı yerleşimleri birleştirir.', 'mikrodalga radyolinkler, noktalı, fiber olmayan yerlerde', 'Burada iki piyasa arasında borsa emirleri gider. Havadan giden sinyal fiberden daha erken ulaşır, çünkü ışık camın içinde daha yavaş ilerler ve borsada saniyenin her milyonda biri önemlidir. Çizgi iki ucu birleştirir: kuleler çizilmez.', 'Yayımlanan gecikme'], 'zh': ['微波中继', '从一座铁塔到另一座铁塔的微波链路：用于城镇之间没有光纤的地方，以及证券交易的高速线路。', '微波中继链路', '在这里，互联网通过空中传输：从一座铁塔到另一座铁塔，借助微波，始终保持视距。它用于铺设光纤不划算或不可能的地方，例如冰原、沙漠或岛屿之间的海面。每座铁塔的位置并未公开：线条连接的是资料中提到的城镇。', '微波中继链路，以虚点表示，用于没有光纤的地方', '这里传递的是两个市场之间的证券交易指令。信号在空气中比在光纤中更快到达，因为光在玻璃中传播得更慢，而在证券交易中，每一微秒都很重要。线条连接两端，不画出铁塔。', '公布的延迟'], 'zh-tw': ['微波中繼', '從一座鐵塔到另一座鐵塔的微波鏈路：用於城鎮之間沒有光纖的地方，以及證券交易的高速路線。', '微波中繼鏈路', '在這裡，網際網路透過空中傳輸：從一座鐵塔到另一座鐵塔，藉由微波，始終保持視距。它用於鋪設光纖不划算或不可能的地方，例如冰原、沙漠或島嶼之間的海面。每座鐵塔的位置並未公開：線條連接的是資料中提到的城鎮。', '微波中繼鏈路，以虛點表示，用於沒有光纖的地方', '這裡傳遞的是兩個市場之間的證券交易指令。訊號在空氣中比在光纖中更快抵達，因為光在玻璃中傳播得更慢，而在證券交易中，每一微秒都很重要。線條連接兩端，不畫出鐵塔。', '公布的延遲'], 'ja': ['無線中継', '鉄塔から鉄塔へとつなぐマイクロ波の中継網：町と町の間に光ファイバーがない場所と、証券取引の高速ルート。', 'マイクロ波無線中継', 'ここではインターネットが空中を伝わります。鉄塔から鉄塔へ、マイクロ波で、常に見通しのきく範囲で。氷原や砂漠、島と島の間の海など、光ファイバーを敷くのが割に合わない、または不可能な場所で使われます。各鉄塔の位置は公開されていません。線は資料に名前のある町を結んだものです。', 'マイクロ波無線中継（点線、光ファイバーのない場所）', 'ここでは2つの市場の間で証券取引の注文が行き交います。光はガラスの中ではより遅く進むため、空中を通る信号は光ファイバーより早く届きます。取引では100万分の1秒が重要です。線は両端を結んだもので、鉄塔は描いていません。', '公表された遅延'], 'ko': ['무선 중계', '철탑에서 철탑으로 이어지는 마이크로파 중계망: 마을 사이에 광섬유가 없는 곳과 증권 거래의 고속 경로.', '마이크로파 무선 중계', '이곳에서는 인터넷이 공중으로 전달됩니다. 철탑에서 철탑으로, 마이크로파로, 항상 가시거리 안에서. 얼음 위나 사막, 섬 사이 바다처럼 광섬유를 까는 것이 수지가 맞지 않거나 불가능한 곳에서 쓰입니다. 각 철탑의 위치는 공개되지 않으며, 선은 자료에 나오는 마을을 이은 것입니다.', '마이크로파 무선 중계(점선, 광섬유가 없는 곳)', '이곳에서는 두 시장 사이에 증권 거래 주문이 오갑니다. 빛은 유리 안에서 더 느리게 움직이기 때문에 공중을 지나는 신호가 광섬유보다 먼저 도착하고, 증권 거래에서는 100만분의 1초가 중요합니다. 선은 양 끝을 이은 것이며 철탑은 그리지 않았습니다.', '공개된 지연 시간'], 'hi': ['रेडियो लिंक', 'टावर से टावर तक माइक्रोवेव की कड़ियाँ: जहाँ कस्बों के बीच फ़ाइबर नहीं है, और शेयर बाज़ार के तेज़ रास्ते।', 'माइक्रोवेव रेडियो लिंक', 'यहाँ इंटरनेट हवा से जाता है: टावर से टावर, माइक्रोवेव से, हमेशा सीधी दृष्टि में। इसका उपयोग वहाँ होता है जहाँ फ़ाइबर बिछाना फ़ायदेमंद या संभव नहीं, जैसे बर्फ़, रेगिस्तान या द्वीपों के बीच का समुद्र। हर टावर की स्थिति सार्वजनिक नहीं है: रेखा स्रोतों में बताए गए कस्बों को जोड़ती है।', 'माइक्रोवेव रेडियो लिंक, बिंदीदार, जहाँ फ़ाइबर नहीं है', 'यहाँ दो बाज़ारों के बीच शेयर बाज़ार के ऑर्डर चलते हैं। हवा से सिग्नल फ़ाइबर से पहले पहुँचता है, क्योंकि काँच के भीतर प्रकाश धीमा चलता है, और शेयर बाज़ार में सेकंड का हर दस लाखवाँ हिस्सा मायने रखता है। रेखा दोनों सिरों को जोड़ती है: टावर नहीं दिखाए गए हैं।', 'प्रकाशित विलंब'], 'bn': ['রেডিও লিংক', 'টাওয়ার থেকে টাওয়ারে মাইক্রোওয়েভের শৃঙ্খল: যেখানে শহরগুলোর মধ্যে ফাইবার নেই, আর শেয়ারবাজারের দ্রুত পথ।', 'মাইক্রোওয়েভ রেডিও লিংক', 'এখানে ইন্টারনেট বাতাসের মধ্য দিয়ে চলে: টাওয়ার থেকে টাওয়ারে, মাইক্রোওয়েভে, সবসময় সরাসরি দৃষ্টিসীমায়। যেখানে ফাইবার বসানো লাভজনক বা সম্ভব নয়, যেমন বরফ, মরুভূমি বা দ্বীপের মাঝের সমুদ্র, সেখানে এটি ব্যবহার হয়। প্রতিটি টাওয়ারের অবস্থান প্রকাশ্য নয়: রেখাটি সূত্রে উল্লেখিত শহরগুলোকে যুক্ত করে।', 'মাইক্রোওয়েভ রেডিও লিংক, বিন্দুযুক্ত, যেখানে ফাইবার নেই', 'এখানে দুই বাজারের মধ্যে শেয়ারবাজারের অর্ডার চলাচল করে। বাতাসে সংকেত ফাইবারের চেয়ে আগে পৌঁছায়, কারণ কাচের ভেতরে আলো ধীরে চলে, আর শেয়ারবাজারে সেকেন্ডের প্রতিটি দশ লক্ষ ভাগের এক ভাগ গুরুত্বপূর্ণ। রেখাটি দুই প্রান্তকে যুক্ত করে: টাওয়ারগুলো আঁকা হয়নি।', 'প্রকাশিত বিলম্ব'], 'id': ['Tautan radio', 'Rantai gelombang mikro dari menara ke menara: di tempat tanpa serat optik antarkota, dan rute cepat bursa saham.', 'Tautan radio gelombang mikro', 'Di sini internet berjalan lewat udara: dari menara ke menara, dengan gelombang mikro, selalu dalam jarak pandang. Ini dipakai di tempat yang tidak menguntungkan atau tidak mungkin dipasangi serat optik, seperti es, gurun, atau laut di antara pulau. Posisi tiap menara tidak dipublikasikan: garisnya menghubungkan kota yang disebut sumber.', 'tautan radio gelombang mikro, bertitik, di tempat tanpa serat optik', 'Di sini order bursa melintas di antara dua pasar. Lewat udara sinyal tiba lebih cepat daripada lewat serat optik, karena cahaya bergerak lebih lambat di dalam kaca, dan di bursa setiap sepersejuta detik berarti. Garisnya menghubungkan kedua ujung: menaranya tidak digambar.', 'Latensi yang dipublikasikan'], 'ms': ['Pautan radio', 'Rantaian gelombang mikro dari menara ke menara: di tempat tiada gentian optik antara pekan, dan laluan pantas bursa saham.', 'Pautan radio gelombang mikro', 'Di sini internet bergerak melalui udara: dari menara ke menara, dengan gelombang mikro, sentiasa dalam garis penglihatan. Ia digunakan di tempat yang tidak berbaloi atau tidak mungkin dipasang gentian optik, seperti ais, gurun atau laut antara pulau. Kedudukan setiap menara tidak didedahkan: garisan menghubungkan pekan yang disebut sumber.', 'pautan radio gelombang mikro, bertitik, di tempat tiada gentian optik', 'Di sini pesanan bursa bergerak antara dua pasaran. Melalui udara isyarat tiba lebih awal daripada melalui gentian optik, kerana cahaya bergerak lebih perlahan di dalam kaca, dan di bursa setiap sepersejuta saat penting. Garisan menghubungkan kedua-dua hujung: menara tidak dilukis.', 'Kependaman yang diterbitkan'], 'vi': ['Vi ba chuyển tiếp', 'Chuỗi vi ba từ trạm này sang trạm khác: ở nơi không có cáp quang giữa các thị trấn, và các tuyến nhanh của sàn chứng khoán.', 'Tuyến vi ba', 'Ở đây internet đi qua không khí: từ trạm này sang trạm khác, bằng vi ba, luôn trong tầm nhìn thẳng. Nó được dùng ở nơi kéo cáp quang không có lợi hoặc không thể, như trên băng, sa mạc hay biển giữa các đảo. Vị trí từng trạm không được công bố: đường kẻ nối các thị trấn mà nguồn nêu tên.', 'tuyến vi ba, nét chấm, ở nơi không có cáp quang', 'Tại đây, lệnh chứng khoán đi giữa hai thị trường. Qua không khí, tín hiệu đến sớm hơn qua cáp quang, vì ánh sáng đi chậm hơn trong thủy tinh, và trên sàn chứng khoán từng phần triệu giây đều quan trọng. Đường kẻ nối hai đầu: không vẽ các trạm.', 'Độ trễ đã công bố'], 'th': ['ลิงก์วิทยุ', 'สายโซ่ไมโครเวฟจากเสาสู่เสา: ในที่ที่ไม่มีไฟเบอร์เชื่อมระหว่างเมือง และเส้นทางความเร็วสูงของตลาดหลักทรัพย์', 'ลิงก์วิทยุไมโครเวฟ', 'ที่นี่อินเทอร์เน็ตเดินทางผ่านอากาศ จากเสาสู่เสาด้วยไมโครเวฟ และต้องมองเห็นกันเสมอ ใช้ในที่ที่วางไฟเบอร์ไม่คุ้มหรือทำไม่ได้ เช่น บนน้ำแข็ง ในทะเลทราย หรือบนทะเลระหว่างเกาะ ตำแหน่งของแต่ละเสาไม่ได้เปิดเผย เส้นนี้เชื่อมเมืองที่แหล่งข้อมูลระบุ', 'ลิงก์วิทยุไมโครเวฟ เส้นประจุด ในที่ที่ไม่มีไฟเบอร์', 'ที่นี่คำสั่งซื้อขายหลักทรัพย์เดินทางระหว่างสองตลาด สัญญาณผ่านอากาศไปถึงเร็วกว่าผ่านไฟเบอร์ เพราะแสงเดินทางช้าลงในแก้ว และในตลาดหลักทรัพย์ทุกหนึ่งในล้านวินาทีมีความหมาย เส้นนี้เชื่อมปลายทั้งสอง ไม่ได้วาดเสา', 'ค่าหน่วงเวลาที่เผยแพร่'], 'ar': ['الوصلات اللاسلكية', 'سلاسل موجات ميكروية من برج إلى برج: حيث لا توجد ألياف بين البلدات، والطرق السريعة للبورصة.', 'وصلة لاسلكية بالموجات الميكروية', 'هنا ينتقل الإنترنت عبر الهواء: من برج إلى برج، بالموجات الميكروية، دائمًا على خط البصر. يُستخدم حيث لا يجدي مدّ الألياف أو يتعذّر، كالجليد أو الصحراء أو البحر بين الجزر. موقع كل برج غير منشور: الخط يصل البلدات التي تذكرها المصادر.', 'وصلات لاسلكية بالموجات الميكروية، منقّطة، حيث لا توجد ألياف', 'هنا تنتقل أوامر البورصة بين سوقين. عبر الهواء تصل الإشارة أسرع منها عبر الألياف، لأن الضوء يسير أبطأ داخل الزجاج، وفي البورصة كل جزء من مليون من الثانية مهم. الخط يصل الطرفين: الأبراج غير مرسومة.', 'زمن الاستجابة المنشور'], 'fa': ['رادیولینک\u200cها', 'زنجیره\u200cهای مایکروویو از دکلی به دکل دیگر: جایی که میان شهرها فیبر نیست، و مسیرهای سریع بورس.', 'رادیولینک مایکروویو', 'اینجا اینترنت از راه هوا می\u200cرود: از دکلی به دکل دیگر، با مایکروویو، همیشه در خط دید. جایی به کار می\u200cرود که کشیدن فیبر به\u200cصرفه یا ممکن نیست، مثل یخ، بیابان یا دریای میان جزیره\u200cها. جای هر دکل عمومی نیست: خط، شهرهایی را که منابع نام برده\u200cاند به هم وصل می\u200cکند.', 'رادیولینک\u200cهای مایکروویو، نقطه\u200cچین، جایی که فیبر نیست', 'اینجا سفارش\u200cهای بورس میان دو بازار جابه\u200cجا می\u200cشود. از راه هوا سیگنال زودتر از فیبر می\u200cرسد، چون نور درون شیشه کندتر حرکت می\u200cکند، و در بورس هر یک\u200cمیلیونیم ثانیه مهم است. خط دو سر را به هم وصل می\u200cکند: دکل\u200cها رسم نشده\u200cاند.', 'تأخیر منتشرشده'], 'he': ['קישורי רדיו', 'שרשראות מיקרוגל מתורן לתורן: במקומות שאין בהם סיב בין היישובים, והנתיבים המהירים של הבורסה.', 'קישור רדיו במיקרוגל', 'כאן האינטרנט עובר באוויר: מתורן לתורן, במיקרוגל, תמיד בקו ראייה. משתמשים בו היכן שהנחת סיב אינה משתלמת או אינה אפשרית, כמו על קרח, במדבר או בים שבין איים. מיקומו של כל תורן אינו פומבי: הקו מחבר את היישובים שהמקורות מזכירים.', 'קישורי רדיו במיקרוגל, מנוקדים, היכן שאין סיב', 'כאן עוברות פקודות בורסה בין שני שווקים. דרך האוויר האות מגיע מהר יותר מאשר דרך סיב, כי האור נע לאט יותר בתוך זכוכית, ובבורסה כל מיליונית שנייה חשובה. הקו מחבר את שני הקצוות: התורנים אינם משורטטים.', 'השהיה שפורסמה'], 'ur': ['ریڈیو لنکس', 'ٹاور سے ٹاور تک مائیکرو ویو کی کڑیاں: جہاں قصبوں کے درمیان فائبر نہیں، اور اسٹاک ایکسچینج کے تیز راستے۔', 'مائیکرو ویو ریڈیو لنک', 'یہاں انٹرنیٹ ہوا کے ذریعے جاتا ہے: ٹاور سے ٹاور، مائیکرو ویو سے، ہمیشہ سیدھی نظر میں۔ یہ وہاں استعمال ہوتا ہے جہاں فائبر بچھانا فائدہ مند یا ممکن نہیں، جیسے برف، صحرا یا جزیروں کے درمیان سمندر۔ ہر ٹاور کا مقام عوامی نہیں: لکیر ان قصبوں کو ملاتی ہے جن کا ذکر ذرائع میں ہے۔', 'مائیکرو ویو ریڈیو لنکس، نقطہ دار، جہاں فائبر نہیں', 'یہاں دو منڈیوں کے درمیان اسٹاک ایکسچینج کے آرڈر چلتے ہیں۔ ہوا کے ذریعے سگنل فائبر سے پہلے پہنچتا ہے، کیونکہ شیشے کے اندر روشنی سست چلتی ہے، اور اسٹاک ایکسچینج میں سیکنڈ کا ہر دس لاکھواں حصہ اہم ہے۔ لکیر دونوں سروں کو ملاتی ہے: ٹاور نہیں دکھائے گئے۔', 'شائع شدہ تاخیر'], 'cs': ['Radioreléové spoje', 'Mikrovlnné řetězce od stožáru ke stožáru: tam, kde mezi obcemi nevede optické vlákno, a rychlé trasy burzy.', 'Mikrovlnný radioreléový spoj', 'Tady internet putuje vzduchem: od stožáru ke stožáru, mikrovlnami, vždy na přímou viditelnost. Používá se tam, kde se optika nevyplatí nebo není možná, například na ledu, v poušti nebo nad mořem mezi ostrovy. Poloha jednotlivých stožárů není veřejná: čára spojuje obce, které uvádějí zdroje.', 'mikrovlnné radioreléové spoje, tečkovaně, kde není optika', 'Tudy putují burzovní příkazy mezi dvěma trhy. Vzduchem dorazí signál dřív než optikou, protože světlo se ve skle šíří pomaleji, a na burze se počítá každá miliontina sekundy. Čára spojuje oba konce: stožáry nejsou zakresleny.', 'Zveřejněná latence'], 'sk': ['Rádioreléové spoje', 'Mikrovlnné reťazce od stožiara k stožiaru: tam, kde medzi obcami nevedie optické vlákno, a rýchle trasy burzy.', 'Mikrovlnný rádioreléový spoj', 'Tu internet putuje vzduchom: od stožiara k stožiaru, mikrovlnami, vždy na priamu viditeľnosť. Používa sa tam, kde sa optika neoplatí alebo nie je možná, napríklad na ľade, v púšti alebo nad morom medzi ostrovmi. Poloha jednotlivých stožiarov nie je verejná: čiara spája obce, ktoré uvádzajú zdroje.', 'mikrovlnné rádioreléové spoje, bodkovane, kde nie je optika', 'Tadiaľto putujú burzové príkazy medzi dvoma trhmi. Vzduchom dorazí signál skôr ako optikou, pretože svetlo sa v skle šíri pomalšie, a na burze sa počíta každá milióntina sekundy. Čiara spája oba konce: stožiare nie sú zakreslené.', 'Zverejnená latencia'], 'ro': ['Radiolegături', 'Lanțuri de microunde din turn în turn: acolo unde nu există fibră între localități, și rutele rapide ale bursei.', 'Radiolegătură prin microunde', 'Aici internetul călătorește prin aer: din turn în turn, prin microunde, mereu în linie de vedere. Se folosește acolo unde fibra nu merită sau nu e posibilă, cum ar fi pe gheață, în deșert sau pe mare între insule. Poziția fiecărui turn nu este publică: linia unește localitățile pe care le numesc sursele.', 'radiolegături prin microunde, punctate, acolo unde nu există fibră', 'Pe aici circulă ordinele de bursă între două piețe. Prin aer semnalul ajunge mai repede decât prin fibră, pentru că lumina merge mai încet în sticlă, iar la bursă contează fiecare milionime de secundă. Linia unește cele două capete: turnurile nu sunt desenate.', 'Latența publicată'], 'hu': ['Mikrohullámú összeköttetések', 'Mikrohullámú láncok toronytól toronyig: ahol a települések között nincs optikai szál, és a tőzsde gyors útvonalai.', 'Mikrohullámú összeköttetés', 'Itt az internet a levegőben halad: toronytól toronyig, mikrohullámon, mindig rálátással. Ott használják, ahol az optika nem éri meg vagy nem lehetséges, például jégen, sivatagban vagy a szigetek közötti tengeren. Az egyes tornyok helye nem nyilvános: a vonal a forrásokban megnevezett településeket köti össze.', 'mikrohullámú összeköttetések, pontozva, ahol nincs optika', 'Itt tőzsdei megbízások haladnak két piac között. A levegőben a jel hamarabb ér célba, mint optikai szálon, mert a fény az üvegben lassabban halad, a tőzsdén pedig minden milliomod másodperc számít. A vonal a két végpontot köti össze: a tornyok nincsenek berajzolva.', 'Közzétett késleltetés'], 'el': ['Μικροκυματικές ζεύξεις', 'Αλυσίδες μικροκυμάτων από πύργο σε πύργο: όπου δεν υπάρχει οπτική ίνα ανάμεσα στους οικισμούς, και οι γρήγορες διαδρομές του χρηματιστηρίου.', 'Μικροκυματική ζεύξη', 'Εδώ το διαδίκτυο ταξιδεύει από τον αέρα: από πύργο σε πύργο, με μικροκύματα, πάντα σε οπτική επαφή. Χρησιμοποιείται όπου η οπτική ίνα δεν συμφέρει ή δεν γίνεται, όπως στον πάγο, στην έρημο ή στη θάλασσα ανάμεσα σε νησιά. Η θέση κάθε πύργου δεν είναι δημόσια: η γραμμή ενώνει τους οικισμούς που αναφέρουν οι πηγές.', 'μικροκυματικές ζεύξεις, με τελείες, όπου δεν υπάρχει οπτική ίνα', 'Εδώ ταξιδεύουν εντολές χρηματιστηρίου ανάμεσα σε δύο αγορές. Από τον αέρα το σήμα φτάνει νωρίτερα απ’ ό,τι από οπτική ίνα, γιατί το φως κινείται πιο αργά μέσα στο γυαλί, και στο χρηματιστήριο μετράει κάθε εκατομμυριοστό του δευτερολέπτου. Η γραμμή ενώνει τα δύο άκρα: οι πύργοι δεν σχεδιάζονται.', 'Δημοσιευμένη καθυστέρηση'], 'bg': ['Радиорелейни връзки', 'Микровълнови вериги от кула до кула: където между селищата няма оптично влакно, и бързите маршрути на борсата.', 'Микровълнова радиорелейна връзка', 'Тук интернетът минава по въздуха: от кула до кула, с микровълни, винаги в пряка видимост. Използва се там, където полагането на оптика не си струва или е невъзможно, като на лед, в пустиня или над морето между острови. Местоположението на всяка кула не е публично: линията свързва селищата, които назовават източниците.', 'микровълнови радиорелейни връзки, пунктирани, където няма оптика', 'Тук между два пазара пътуват борсови поръчки. По въздуха сигналът пристига по-бързо, отколкото по оптика, защото светлината се движи по-бавно в стъклото, а на борсата всяка милионна от секундата има значение. Линията свързва двата края: кулите не са начертани.', 'Публикувано закъснение'], 'hr': ['Radiorelejne veze', 'Mikrovalni lanci od tornja do tornja: gdje između naselja nema optike, i brze rute burze.', 'Mikrovalna radiorelejna veza', 'Ovdje internet putuje zrakom: od tornja do tornja, mikrovalovima, uvijek u liniji vidljivosti. Koristi se gdje se optika ne isplati ili nije moguća, kao na ledu, u pustinji ili na moru između otoka. Položaj svakog tornja nije javan: crta spaja naselja koja navode izvori.', 'mikrovalne radiorelejne veze, točkasto, gdje nema optike', 'Ovuda putuju burzovni nalozi između dvaju tržišta. Zrakom signal stiže prije nego optikom, jer se svjetlost u staklu kreće sporije, a na burzi se broji svaki milijunti dio sekunde. Crta spaja dva kraja: tornjevi nisu ucrtani.', 'Objavljena latencija'], 'fil': ['Mga radio link', 'Mga kadena ng microwave mula tore hanggang tore: kung saan walang fiber sa pagitan ng mga bayan, at ang mabibilis na ruta ng stock market.', 'Microwave radio link', 'Dito, dumaraan sa hangin ang internet: mula tore hanggang tore, sa microwave, laging magkatanaw. Ginagamit ito kung saan hindi sulit o hindi posible ang fiber, gaya ng yelo, disyerto o dagat sa pagitan ng mga isla. Hindi pampubliko ang lokasyon ng bawat tore: pinagdudugtong ng linya ang mga bayang binabanggit ng mga pinagmulan.', 'mga microwave radio link, may tuldok, kung saan walang fiber', 'Dito dumaraan ang mga order ng stock market sa pagitan ng dalawang merkado. Sa hangin, mas maagang dumarating ang signal kaysa sa fiber, dahil mas mabagal ang liwanag sa loob ng salamin, at sa stock market mahalaga ang bawat milyong bahagi ng segundo. Pinagdudugtong ng linya ang dalawang dulo: hindi iginuhit ang mga tore.', 'Inilathalang latency'], 'sw': ['Viungo vya redio', 'Minyororo ya mawimbi madogo kutoka mnara hadi mnara: mahali pasipo na fiber kati ya miji, na njia za haraka za soko la hisa.', 'Kiungo cha redio cha mawimbi madogo', 'Hapa intaneti husafiri hewani: kutoka mnara hadi mnara, kwa mawimbi madogo, kila mara kwa kuonana moja kwa moja. Hutumika pale ambapo kuweka fiber hakulipi au hakuwezekani, kama kwenye barafu, jangwani au baharini kati ya visiwa. Mahali pa kila mnara si pa umma: mstari unaunganisha miji inayotajwa na vyanzo.', 'viungo vya redio vya mawimbi madogo, vya nukta, mahali pasipo na fiber', 'Hapa maagizo ya soko la hisa husafiri kati ya masoko mawili. Kupitia hewani ishara hufika mapema kuliko kupitia fiber, kwa sababu mwanga husafiri polepole zaidi ndani ya kioo, na katika soko la hisa kila sehemu ya milioni ya sekunde ni muhimu. Mstari unaunganisha ncha mbili: minara haijachorwa.', 'Ucheleweshaji uliochapishwa'], 'ta': ['வானொலி இணைப்புகள்', 'கோபுரத்திலிருந்து கோபுரத்திற்கு நுண்ணலைச் சங்கிலிகள்: ஊர்களுக்கு இடையே ஃபைபர் இல்லாத இடங்களிலும், பங்குச் சந்தையின் விரைவுப் பாதைகளிலும்.', 'நுண்ணலை வானொலி இணைப்பு', 'இங்கே இணையம் காற்றின் வழியே செல்கிறது: கோபுரத்திலிருந்து கோபுரத்திற்கு, நுண்ணலையால், எப்போதும் நேர்ப்பார்வையில். ஃபைபர் போடுவது லாபமில்லாத அல்லது இயலாத இடங்களில், பனி, பாலைவனம், தீவுகளுக்கு இடையிலான கடல் போன்றவற்றில் இது பயன்படுகிறது. ஒவ்வொரு கோபுரத்தின் இடமும் பொதுவில் இல்லை: கோடு, ஆதாரங்கள் குறிப்பிடும் ஊர்களை இணைக்கிறது.', 'நுண்ணலை வானொலி இணைப்புகள், புள்ளிக்கோடாக, ஃபைபர் இல்லாத இடங்களில்', 'இங்கே இரண்டு சந்தைகளுக்கு இடையே பங்குச் சந்தை உத்தரவுகள் செல்கின்றன. கண்ணாடிக்குள் ஒளி மெதுவாகச் செல்வதால், காற்றின் வழியே சமிக்ஞை ஃபைபரை விட முன்னதாகச் சேர்கிறது; பங்குச் சந்தையில் ஒவ்வொரு மில்லியனில் ஒரு வினாடியும் முக்கியம். கோடு இரு முனைகளையும் இணைக்கிறது: கோபுரங்கள் வரையப்படவில்லை.', 'வெளியிடப்பட்ட தாமதம்'], 'te': ['రేడియో లింకులు', 'టవర్ నుంచి టవర్\u200cకు మైక్రోవేవ్ గొలుసులు: పట్టణాల మధ్య ఫైబర్ లేని చోట, మరియు స్టాక్ మార్కెట్ వేగవంతమైన మార్గాల్లో.', 'మైక్రోవేవ్ రేడియో లింక్', 'ఇక్కడ ఇంటర్నెట్ గాలి ద్వారా వెళ్తుంది: టవర్ నుంచి టవర్\u200cకు, మైక్రోవేవ్\u200cతో, ఎప్పుడూ నేరుగా కనిపించే దూరంలో. ఫైబర్ వేయడం లాభం లేని లేదా సాధ్యం కాని చోట, మంచు, ఎడారి లేదా దీవుల మధ్య సముద్రం వంటి చోట దీన్ని వాడతారు. ప్రతి టవర్ స్థానం బహిరంగం కాదు: గీత ఆధారాలు పేర్కొన్న పట్టణాలను కలుపుతుంది.', 'మైక్రోవేవ్ రేడియో లింకులు, చుక్కల గీతతో, ఫైబర్ లేని చోట', 'ఇక్కడ రెండు మార్కెట్ల మధ్య స్టాక్ మార్కెట్ ఆర్డర్లు ప్రయాణిస్తాయి. గాజులో కాంతి నెమ్మదిగా ప్రయాణిస్తుంది కాబట్టి, గాలి ద్వారా సంకేతం ఫైబర్ కంటే ముందుగా చేరుతుంది; స్టాక్ మార్కెట్\u200cలో ప్రతి మిలియన్\u200cవ వంతు సెకను ముఖ్యమే. గీత రెండు చివరలను కలుపుతుంది: టవర్లు గీయలేదు.', 'ప్రచురించిన ఆలస్యం']}


def main(raiz):
    d = os.path.join(raiz, 'orbita', 'static', 'i18n')
    for f in sorted(os.listdir(d)):
        if not f.endswith('.json'): continue
        c = f[:-5]
        if c not in T: sys.exit('falta ' + c)
        p = os.path.join(d, f); raw = open(p, encoding='utf-8').read(); j = json.loads(raw)
        for k, v in zip(K, T[c]): j['t'][k] = v
        open(p, 'w', encoding='utf-8').write(json.dumps(j, ensure_ascii=False, indent=1) + ('\n' if raw.endswith('\n') else ''))
    p = os.path.join(raiz, 'orbita', 'static', 'idioma.js'); s = open(p, encoding='utf-8').read()
    ancla = "    'De compañías con 1 a 4 centros de datos en el mapa, o sin operador conocido.':"
    i = s.index(ancla); i = s.index('\n', i) + 1
    nuevas = ''.join('    %s: [%s, %s],\n' % (json.dumps(k, ensure_ascii=False), json.dumps(e, ensure_ascii=False), json.dumps(pt, ensure_ascii=False)) for k, e, pt in zip(K, T['en'], T['pt']) if json.dumps(k, ensure_ascii=False) + ':' not in s)
    open(p, 'w', encoding='utf-8').write(s[:i] + nuevas + s[i:])
    print('ok', len(T))

if __name__ == '__main__':
    main(sys.argv[1])
